contract InvMutTest {
    C c;
    address[] public seenTo;
    uint256 public seenFromSlot;
    address public seenFrom;
    uint256 public seenV;
    bool public callCountMatches;
    uint256 public nCalls;
    uint256 public tosLen;

    constructor(C _c) { c = _c; }

    function run(address from, address[] memory tos, uint v) public {
        require(tos.length > 0);
        require(nCalls == 0);
        tosLen = tos.length;
        bool ok = c.transfer(from, address(this), tos, v);
        assert(ok == true && nCalls == tos.length && callCountMatches);
        for (uint i = 0; i < tos.length; i++) {
            assert(seenTo[i] == tos[i]);
        }
        assert(seenFrom == from && seenV == v);
    }

    fallback() external payable {
        bytes4 id = bytes4(keccak256("transferFrom(address,address,uint256)"));
        if (msg.sig == id && msg.data.length == 100) {
            address f;
            address to;
            uint256 val;
            assembly {
                f := mload(add(msg.data, 0x24))
                to := mload(add(msg.data, 0x44))
                val := mload(add(msg.data, 0x64))
            }
            if (nCalls == 0) {
                seenFrom = f;
                seenV = val;
            } else {
                if (f != seenFrom || val != seenV) {
                    callCountMatches = false;
                }
            }
            seenTo.push(to);
            nCalls++;
            assembly {
                mstore(0x00, 0x01)
                return(0x00, 0x20)
            }
        }
    }

    receive() external payable {}
}

